-- v0.13: mapeo raza + clase -> capas de ficha (PC e Imprimir) y combo_id en characters. Se puede ejecutar varias veces.
CREATE TABLE IF NOT EXISTS public.fichas_combinaciones (
  id text PRIMARY KEY,
  raza_id text NOT NULL,
  raza_nombre text NOT NULL,
  clase_id text NOT NULL,
  clase_nombre text NOT NULL,
  pc_capa_raza text NOT NULL,
  pc_capa_clase text NOT NULL,
  pc_clase_x integer NOT NULL,
  pc_clase_y integer NOT NULL,
  pc_clase_ancho integer NOT NULL,
  pc_clase_alto integer NOT NULL,
  imp_capa_raza text NOT NULL,
  imp_capa_clase text NOT NULL,
  imp_clase_x integer NOT NULL,
  imp_clase_y integer NOT NULL,
  imp_clase_ancho integer NOT NULL,
  imp_clase_alto integer NOT NULL
);

ON CONFLICT (id) DO UPDATE SET
  raza_id = EXCLUDED.raza_id, raza_nombre = EXCLUDED.raza_nombre, clase_id = EXCLUDED.clase_id, clase_nombre = EXCLUDED.clase_nombre,
  pc_capa_raza = EXCLUDED.pc_capa_raza, pc_capa_clase = EXCLUDED.pc_capa_clase,
  pc_clase_x = EXCLUDED.pc_clase_x, pc_clase_y = EXCLUDED.pc_clase_y, pc_clase_ancho = EXCLUDED.pc_clase_ancho, pc_clase_alto = EXCLUDED.pc_clase_alto,
  imp_capa_raza = EXCLUDED.imp_capa_raza, imp_capa_clase = EXCLUDED.imp_capa_clase,
  imp_clase_x = EXCLUDED.imp_clase_x, imp_clase_y = EXCLUDED.imp_clase_y, imp_clase_ancho = EXCLUDED.imp_clase_ancho, imp_clase_alto = EXCLUDED.imp_clase_alto;

-- Personajes existentes quedan con combo_id NULL (no se inventa combinación).
ALTER TABLE public.characters ADD COLUMN IF NOT EXISTS combo_id text REFERENCES public.fichas_combinaciones(id);
